# -*- coding: utf-8 -*-
"""Stage 3 merge for report 76 (Way of Life - Habit Tracker, Way of Life ApS)."""
import json
C = {x["id"]: x for x in json.load(open("Tools/prd_ledger/canonical.json"))}
def ext(cid, text):
    if text not in C[cid]["statement"]: C[cid]["statement"] += text
def add(cid, section, title, statement):
    if cid in C: return
    C[cid] = dict(id=cid, title=title, statement=statement, section=section, cards=[], reports=[], merged_from=[])

add("C294", "do", "When the pricing model changes, the historical review corpus keeps advertising the old one — state the current model on the listing and paywall, and honour every old receipt automatically",
    "Report 76 (Way of Life, 7,764 reviews over 16 years): premium was a $4.99 one-time unlock from 2010 and became a subscription in 2023; in the subscription era (E6, 906 reviews) MON_SUBSCRIPTION is 40 reviews at mean 2.70★ (4.42% of the era, 15 of the corpus's 181 1★) and splits three ways — lifetime buyers told to subscribe again ('Ich hab mir die App 2015 oder so als voll Version gekauft', 1★; '之前永久内购没了？重新订阅？', 1★), new users who arrived expecting the one-time price because 'reviews said it was a one time payment' (3★), and prices differing week to week ('last week the price was $29, this week is $99', 4★); some veterans were grandfathered ('grandfathered into the new system', 5★), so the path existed but was not reliable; restore failures rose 0.91% → 1.55% and support silence peaked (SUP_NONE 9 of 20 in E6). A decade of 5★ reviews praising 'a one time charge' keeps recruiting users who then feel misled; §8.1 restore premium for any old receipt on any device without a subscription prompt, and show one stable price per region stating monthly / annual / lifetime. Related: [[C186]] (never revoke what earlier buyers paid for), [[C218]] (listing copy stays true), [[C113]] (one stable disclosed price), [[C003]] (lead with lifetime).")

add("C295", "must-never-break", "Backup and sync must run on infrastructure reachable in every storefront the app is sold in — a blocked provider makes the app's data unsafe in that market",
    "Report 76 (Way of Life): backup was Dropbox-only in the early years; 17 of the 18 NEG_DROPBOX_BLOCKED complaints are from the Chinese storefront (2014-07-18 → 2016-03-08; 'Dropbox中国区都屏蔽了吧' — Dropbox is blocked in China, 3★), the other from sg; cn also carries BUG_BACKUP 5 (7.35× global) and REQ_BACKUP 9 (6.30×), and was the app's second-largest storefront (528 reviews) before it went quiet after 2018 (never more than 12 reviews a year). A backup path that a market cannot reach is, for that market, no backup: data loss follows on the next phone change. Related: [[C132]] (do not sell where the app cannot function), [[C034]] (data never lost), [[C153]] (automatic cloud backup on by default), [[C026]] (markets where rails fail).")

ext("C006", " Report 76 (Way of Life, 7,764 reviews / 16 years): simplicity is the product — U_SIMPLICITY 1682 (21.66%), PR_SIMPLE 17.0–22.5% in every era; PR_KEEP_SIMPLE 64 ('Please do not change a single thing'), 61 of them in E5–E6 where TENURE_LONG is 20.6% of reviews — the request to freeze the product grows with tenure; Germany asks it 4.62× the global rate; 'Product Managers should study this app'; boomerang users come back to it after heavier apps (CHURN_RETURN 60 > U_CHURN 55); the cost is NEG_SIMPLE 43 (2.98★) who leave for a tally sheet.")
ext("C178", " Report 76 (Way of Life): 'I've possibly tried every habit app, and keep coming back to this one' (the most-voted review, 20 votes); 'I just always end up coming back to the simplicity of Way of Life'; PR_BETTER_THAN 428 (5.51%) is said comparatively; NEG_SIMPLE 43 / NEG_POINTLESS 15 ('I can do the same with a simple tally sheet', 2★) is the accepted price of the position.")
ext("C043", " Report 76 (Way of Life): the one structural request for fifteen years — U_FLEX_REQ 347 (4.47%, mean 4.13★) = REQ_FREQUENCY 214 (weekdays, N times a week, weekly/monthly) + REQ_COUNT 129 (quantities) + NEG_YESNO 36 (a partial state); present in 15 of 16 calendar years and in every era (1.8–4.5%); the most frequent code in 4★ after generic praise (96 of 1,281) and 2.39× more common among purchasers than the corpus; a 2016 reviewer was 'waiting for the promised weekly/monthly options' and they never came (NEG_DEV_PROMISE); users emulate it with skip, which distorts the percentages they value (NEG_CHART 38); §8.4 schedule on weekdays or N/week with non-scheduled days neutral and excluded from percentages, counts as a separate journal type, yes/no as the default, guarding against bloat (PR_KEEP_SIMPLE 64).")
ext("C256", " Report 76 (Way of Life): the three-state grid (yes / no / skip) is praised (PR_SKIP 99, PR_YESNO 73), but without scheduled frequency skip becomes a scheduling method ('I try to only use skips for actual exceptions to habits, not as a scheduling method', 3★) and corrupts the stats (NEG_CHART 38); §8.4: non-scheduled days must be neutral and excluded from percentages.")
ext("C016", " Report 76 (Way of Life): a skip state that keeps the chain is loved — 'skip option for when you have days where you need to skip without breaking your chain'; PR_SKIP 99 (1.28%, 4.66★); the request REQ_SKIP (7, 2011) stopped the moment it shipped (2012-05).")
ext("C019", " Report 76 (Way of Life): good and bad habits in one grid, colours inverting for habits to avoid — 'it reverses the red/green colours for yes and no' (5★); PR_YESNO 73; USE_ADDICTION 46 at mean 4.96★ ('Today marks 1 month clean'); REQ_NEUTRAL_HABIT 5 want a third, neutral kind.")
ext("C012", " Report 76 (Way of Life): the at-a-glance grid of green/red/grey cells plus charts is the second-largest praise (PR_INSIGHTS 838, 10.79%, 4.80★) and the #2 purchase trigger (14.3% of 349 purchasers: 'This is the only app I bought the paid version for, and I regret it not at all'); honesty through colour is the motivator — 'keeps me from fooling myself into thinking I did better than I really did'; 'I hate to break a winning steak'; PR_ACCOUNTABILITY 477 (6.14%).")
ext("C234", " Report 76 (Way of Life): charts, trends and overview are free for the 3-item tier and are the second-largest praise (PR_INSIGHTS 838); friction is about range and depth (REQ_STATS 72, REQ_DATE_RANGE 22, REQ_CALENDAR 29, NEG_CHART 38), not access.")
ext("C007", " Report 76 (Way of Life): a 3-item free cap held for 16 years; MON_FREE_LIMIT 250 (3.22%, 3.53★, in every era 1.5–6.1%, peaking in E3) vs PR_FREE 249 (4.72★) — 'I actually think three habits is enough'; 'forced me to prioritize the three most important tasks by paywalling more than 3' (5★); cn: 'the free version's limit of three habits is actually better'; the cap is the #1 purchase trigger once the free tier has delivered value ('found myself wanting to add more and shelled out the $5'); 2★ reviews are 25% MON_FREE_LIMIT; 1★ 18.78%.")
ext("C222", " Report 76 (Way of Life): the 3-item cap is defended by users as a focusing device (#7013, #4439, #6073) and §8.8 says keep it; the objection never went away (every era) but fell from 6.1% (E3) to 1.5% (E6).")
ext("C147", " Report 76 (Way of Life): 'only by buying will you know if you need it' (ua 2★); 'This is not a Free app with in-app purchases. This is a $7 app' (1★); REQ_TRIAL 4 at mean 1.75★; §8.9 Q4 asks whether the 3-item tier converts better or worse than a time-limited full trial.")
ext("C063", " Report 76 (Way of Life): three items is too few to evaluate for some (REQ_TRIAL 4, 1.75★); the subscription era added a free trial ('My trial ends Saturday', 2★).")
ext("C003", " Report 76 (Way of Life): a $4.99 one-time unlock sustained a 4.62★ corpus for 13 years — MON_VALUE 342 (4.40%, mean 4.90★): 'it is a one time charge and it unlocks the full capabilities of the app'; 84.2% of 349 self-reported purchasers rate 4–5★; after the 2023 switch reviewers still ask for it: 'happy to pay up to £50 even for lifetime access' (3★), 'I'm not paying a yearly subscription'; §8.6 experiment: a published lifetime price alongside the subscription, measuring purchase mix and 1★ share among new users.")
ext("C186", " Report 76 (Way of Life): the 2023 subscription switch — lifetime buyers from 2015 told they no longer have premium (1★, de/kz/cn), restore failures up to 1.55% of E6, 15 of 181 corpus 1★; grandfathering existed ('grandfathered into the new system', 5★) but was unreliable; §8.1 restore for any old App Store receipt on any device without a subscription prompt.")
ext("C033", " Report 76 (Way of Life): BUG_PURCHASE 54 (0.70%, mean 2.69★) runs the whole 16 years and is 9.48× over-represented among purchasers and 11.60% of 1★; 'money were taken but nothing had changed' (ru 1★); 'es gebe nichts zum wiederherstellen' (de 1★); rose after the model change (0.91% → 1.55%); ru over-indexes 3.29×.")
ext("C065", " Report 76 (Way of Life): 1★ (181) is where purchases go wrong — MON_PAID 16.57%, BUG_PURCHASE 11.60%, MON_SUBSCRIPTION 8.29%, MON_REGRET 7.18%, MON_DISCLOSURE 7.73%, SUP_NONE 6.08%; MON_REGRET is the lowest-rated money code (21, mean 1.52★); 40 of 349 purchasers (11.5%) rate 1–2★; on cn 11 reviews in one week of 2015-01 report crashing immediately after buying premium ('the money was taken and it started crashing, endlessly').")
ext("C113", " Report 76 (Way of Life): 'last week the price was $29, this week is $99' (4★) in the subscription era; §8.1 one stable price per region stating whether it is monthly, annual or lifetime; 'only offer a reduced price in the first days after installation' (br 5★) penalises evaluators.")
ext("C236", " Report 76 (Way of Life): MON_DISCLOSURE 33 (0.43%, mean 2.06★) — 'not particularly clear in the iTunes store that the free app allows for only three categories' (2★); 7.73% of 1★ and 6.73% of 2★ carry it.")
ext("C218", " Report 76 (Way of Life): the listing still marks 'backup to cloud' as premium while 4.3.0 release notes say it is free for all; declared languages omit Kazakh and Galician that reviewers asked for; the listing cites Tim Ferriss / Kevin Rose and reviewers name the same source — the listing's press citations are corroborated by the corpus.")
ext("C064", " Report 76 (Way of Life): the $4.99 objection peaked when the app was young and the free tier had ads (MON_PRICE 6.7% E2, 6.5% E3) and fell to 1.6% in E5 as it matured; prices users volunteer — 12 yuan (cn), 200 roubles (ru), '.99 for an extra goal' (a per-item micro-price), 'up to £50 for lifetime' (gb); the price objection carries mean 3.71★ and is 23.49% of 3★ — 3★ reviews are the longest because they argue price.")
ext("C092", " Report 76 (Way of Life): China carries 82 of 306 price objections (26.8%); MON_PRICE is 15.5% of cn reviews (3.94×) and several name the price at which they would buy — '价格太贵了，要是12块我就买了' (at 12 yuan I would buy it, 5★); '30块也是最贵的' (at 30 yuan also the most expensive); East Asia group price objection 16.9% vs 7.5% global; the US sits at 4.8%.")
ext("C062", " Report 76 (Way of Life): the six storefronts with the most public ratings (us, ru, ca, de, gb, jp — an install-base proxy) run 6.1% price objection vs 7.5% global and 16.9% in East Asia; the US (40.12% of reviews) sets the global profile; cn's second-largest volume in 2014–15 vanished after 2018 (≤12 reviews/yr).")
ext("C034", " Report 76 (Way of Life): local-only storage with manual backup — U_DATA_RISK 123 (1.58%, mean 3.04★): BUG_DATA_LOSS 38, NEG_BACKUP_MANUAL 13, BUG_BACKUP 10; long histories gone on update or phone change ('using Way of Life daily for over four years… I downloaded an update and all of my data disappeared', 2★; 'for the third time, I've lost my data because I forgot to backup my data', 3★; 'I lost all my habits when I got a new phone even though I paid for the app', 5★); a 2017-07 release wiped some histories; 12 of 181 1★ are data loss.")
ext("C153", " Report 76 (Way of Life): cloud backup was a premium feature until v4.3.0 (2026) made 'Backup & Restore free for all users' — §8.2 notes that addresses cost, not the default: automatic, silent iCloud backup on by default and a restore check before any update migrates data; REQ_AUTO_BACKUP 12; NEG_BACKUP_MANUAL 13 (2.77★).")
ext("C176", " Report 76 (Way of Life): 'I lost all my habits when I got a new phone even though I paid for the app' (5★) — cloud backup sold as premium for most of the app's life, then made free in 4.3.0.")
ext("C085", " Report 76 (Way of Life): the same local-only design draws PR_PRIVACY 12 (4.92★, 'Local data, no account') and BUG_DATA_LOSS 38 — privacy praise and data-loss complaints come from one decision; the answer is default backup, not an account.")
ext("C013", " Report 76 (Way of Life): REQ_SYNC 139 (1.79%, 4.01★) in every era for 14 years, second most frequent request, 2.72× over-represented among purchasers; 'at this point I would pay to sync' (5★); 'A five star app without iCloud support is a one star app' (gb 1★); 'Five stars if I could open the app on any device and see my data' (3★); REV_STAR_TACTIC 19 make the fifth star conditional; §8.5 ship iCloud sync to iPad before a Watch app — sync is the paid feature reviewers say they would pay for.")
ext("C141", " Report 76 (Way of Life): REQ_IPAD 123 (1.58%) dominated the early years (E1 4.7%) and is still the second device most named; §8.5 iPad before Watch; 'you have to pay for each iPhone or iPad you use' (1★) when purchases did not carry across.")
ext("C022", " Report 76 (Way of Life): REQ_WATCH 54 (0.70%, 4.30★) appears from 2015-08 and replaces the iPad request from 2016 (E5 1.8%); §8.5 ranks it after iCloud sync to iPad.")
ext("C009", " Report 76 (Way of Life): REQ_WIDGET 41 (0.53%) from 2014-11; the 2023 removal of the old Today widget drew NEG_LOST_FEATURE 7 ('Any updates on when the widget will be fixed?', 3★); widgets shipped for iOS 17+.")
ext("C044", " Report 76 (Way of Life): REQ_MAC 23 (4.52★), REQ_WEB 14 (4.43★), REQ_ANDROID 3 — the highest-rated requests in the list, from users who already love it.")
ext("C175", " Report 76 (Way of Life): U_UPDATE_REGRESSION 84 (1.08%, mean 3.08★); BUG_UPDATE_BROKE 54 (2.80★) — 21 from 2012-11/12 (a release that left the app unusable or corrupted data: 'latest release has left this application unusable'), 12 from 2016-05/06 (crash on 'updating journal' at launch; reviews from six countries within two days), a 2017-07 release that wiped histories ('Latest update deleted my entire history', 5★), the 2014-06 v3.0 flat redesign called awful and greedy (NEG_UPDATE_WORSE 17), the 2023 loss of the Today widget; 10.50% of 1★; the two worst months in 16 years (2012-11 at 4.38★, 2015-01 at 4.36★) are both regressions.")
ext("C031", " Report 76 (Way of Life): BUG_CRASH 39 (0.50%, mean 2.08★) in two waves — 11 on cn in one week of 2015-01 immediately after buying premium, 10 in 2016-05 after an update; BUG_LAUNCH 4; 10.50% of 1★.")
ext("C119", " Report 76 (Way of Life): the 2014-06 version 3.0 flat redesign split users — 'new version (3.0) looks awful' (2★), NEG_UPDATE_WORSE 8 of 17 in that era — and marks an era boundary in the review series; NEG_DESIGN 70 (0.90%) runs 2011 → 2023.")
ext("C059", " Report 76 (Way of Life): fast fixes turn regression reviewers around — PR_SUPPORT 68 (4.79★) and REV_UPDATED 74 include reviewers who returned to raise their stars ('Has been fixed - good response', 5★); through 2016 'developer emailed me back in less than 5 minutes', 'solved within a day'; gb over-indexes on support praise 2.75×.")
ext("C036", " Report 76 (Way of Life): support silence arrives from 2016 and peaks in the subscription era (SUP_NONE 20 at mean 2.05★, 9 of them in E6) alongside restore failures; the website contact section did not work ('secção de Contact no website não funciona', pt 1★); 'received no response at all' (1★); §8.3 a working in-app contact form and an auto-reply with restore steps; reviewers excuse a solo developer ('I think they are just one person, so be patient') until money is involved.")
ext("C239", " Report 76 (Way of Life): a named solo developer is part of the product — PR_DEV 268 (3.45%, mean 4.96★) rising from 2.1% of E1 to 6.7% of E6, thanked for 'steady updates' over a decade; ru 1.99×, kz 4.06×, ua 2.68×; §8.8 keep 'one-person, responsive development'.")
ext("C071", " Report 76 (Way of Life): NEG_SLOW_DEV 20 (3.50★) and NEG_DEV_PROMISE 6 (2013 → 2026) — 'Can't wait for the promised weekly/monthly options' (2016) is still unmet in 2026; PR_UPDATE 255 (4.91★, 'updates improve it') is the counter-signal in most eras.")
ext("C094", " Report 76 (Way of Life): 20 days carry 20+ reviews (520, 6.70%, 86.15% 5★) after updates and in-app rating prompts, no campaign marks; the prompt draws resentment when mistimed — 'Quit bugging me with review me review me crap' (1★); 'app solicited a review 3 days in, after I paid for the premium version' (4★); §8.7 suppress the prompt for 30 days after a purchase or a crash-free launch following a failure; REV_SOLICITED 18 (4.06★).")
ext("C150", " Report 76 (Way of Life): 'app solicited a review 3 days in, after I paid for the premium version' (4★) — prompting right after a purchase reads as a second ask.")
ext("C231", " Report 76 (Way of Life): a praise corpus (any-praise 81.88%, 1–2★ 3.67%) where a 'Meaningful' complaint is dozens of reviews; CONTRA_RATING 47 (0.61%) — 29 high-star reviews reporting problems, 7 low-star praise ('I absolutely love this app', 1★); the public mean exceeds the corpus mean in 21 of 22 storefronts; E6 is both the highest-rated era (4.70) and the most polarised (1–2★ 5.2%); removing burst days shifts no headline by more than 0.4 pp.")
ext("C002", " Report 76 (Way of Life): mean rose every era 4.51 → 4.70 while 1–2★ also rose 2.2% → 5.2% — the subscription era is carried by veterans (TENURE_LONG 20.6%) and developer praise, with the offer objection (MON_SUBSCRIPTION 4.4% of E6) underneath; 4★ reviews are 'the same praise with one missing thing' (frequency 96, price 100, free limit 81, sync 62 of 1,281).")
ext("C127", " Report 76 (Way of Life): ads briefly appeared for paying users after the 2015-11 update ('Ads when already paid', 2★) and a 2020-01 bundle promotion shown to paying users drew 5 complaints ('Ads now constantly appear in paid version', 4★) — the last ad complaints in the corpus are from payers.")
ext("C082", " Report 76 (Way of Life): the free tier carried ads 2011 → ~2018 (NEG_ADS 54, mean 3.06★, 5.03% of 3★); removing them was the #3 purchase trigger ('Worth the upgrade to get rid of the ads', 4.6% of purchasers, 6.59× lift); ads gone from the free version by 2018 ('Now without ads even in free version', 5★) and NEG_ADS is 0.0% of E6; the price objection was highest while the free tier had ads (E2–E3) and fell after.")
ext("C246", " Report 76 (Way of Life): ad removal as the paid unlock's side benefit was worth paying for (6.59× lift among purchasers) and the objection vanished once the free tier went ad-free in 2018.")
ext("C097", " Report 76 (Way of Life): a tip jar from 2018-11 — MON_TIP 15 (4.60★): 'jumped at the chance to tip the developers' (au 5★); 'supporting the developer' is a named purchase trigger in a corpus that thanks the developer by name (PR_DEV 268).")
ext("C061", " Report 76 (Way of Life): PR_FREE 249 (4.72★) 'free version is enough' and the cap converts only after the free tier has delivered value — 'found myself wanting to add more and shelled out the $5'; 'bought the upgrade to have more than three lines to track'; MON_INTENT 93 (4.65★).")
ext("C133", " Report 76 (Way of Life): premium = unlimited items only; purchasers still ask for frequency (2.39×) and sync (2.72×) more than the corpus — the paid tier unlocks more of the same rather than the two capabilities people want; §8.5 sync is the paid feature reviewers say they would pay for.")
ext("C058", " Report 76 (Way of Life): press and podcasts are the named acquisition source — MKT_PRESS 51 (0.66%, mean 4.94★), 26 in E4 (Tim Ferriss's podcast with Kevin Rose, Ezra Klein), later Atomic Habits, and in ru/kz Margulan Seisembay ('Спасибо Маргулану Сейсембаю'); 6 purchasers cite press ('Used for one day then upgraded to the paid'); coaches and clinicians recommend it to clients (USE_COACH 20, 4.95★); gb 2.20×, au 3.11×.")
ext("C070", " Report 76 (Way of Life): Atomic Habits is a named acquisition source in later eras; the app predates the book and reviewers map it onto the grid.")
ext("C134", " Report 76 (Way of Life): the listing cites Tim Ferriss / Kevin Rose and reviewers cite the same source for a decade — earned press in the listing compounds; §8.8 keep the three-state grid, the charts, the 3-habit free tier and one-person development in front.")
ext("C042", " Report 76 (Way of Life): USE_ADHD 23 (4.91★), USE_MENTAL 27 ('someone who lives with a mood disorder'; 'I used this to get me out of a rough depression'), USE_ADDICTION 46 (4.96★), USE_COACH 20 (4.95★) — all above the corpus mean.")
ext("C067", " Report 76 (Way of Life): USE_FITNESS 98 (1.26%), USE_HEALTH 71, USE_DIET 56 — 'go from 210 pounds to 164 pounds'; OUT_HEALTH 16 at 5.00★.")
ext("C103", " Report 76 (Way of Life): USE_ADDICTION 46 (4.96★, 'Today marks 1 month clean'), USE_MENTAL 27, USE_ADHD 23 — the sobriety and mental-health cohorts rate highest in a 4.62★ corpus.")
ext("C216", " Report 76 (Way of Life): the percentage/grid measure is what users protect — misusing skip to emulate a weekly habit 'distorts the percentages they value' (NEG_CHART 38); OUT_AWARENESS 181 (self-awareness) is the outcome the grid produces.")
ext("C024", " Report 76 (Way of Life): chains shipped 2015-11 and turned a request into praise — PR_CHAINS 0.3% E1 → 3.2% E4 (56 reviews, 'Chains is going to change my life') → 3.2% E6; REQ_STREAKS fell 18 → 3; REQ_GAMIFY 16 (4.06★) stays small; the red cell, not a reward, is the motivator ('I hate to break a winning steak').")
ext("C008", " Report 76 (Way of Life): reminders are free and praised (PR_REMINDERS 351, 4.83★) but the praise fades from 6.6% of E1 to 1.8% of E6 as reminders become table stakes; per-item reminders were requested for eight years (REQ_REMINDER_PER_ITEM 51, 2011 → 2019) and the request stopped when they shipped.")
ext("C014", " Report 76 (Way of Life): REQ_REMINDER_PER_ITEM 51 (0.66%) from 2011-04 to 2019-03 and zero after — consistent with per-item reminders shipping; REQ_REMINDER_REPEAT 9, REQ_REMINDER_SCHEDULE 8.")
ext("C252", " Report 76 (Way of Life): REQ_NOTIF_ACTION 6 — complete from the notification (2015 → 2025).")
ext("C123", " Report 76 (Way of Life): NEG_BADGE 13, NEG_NOTIF 11 (2.27★) sit beside NEG_FORGET 14 'forgets to log' — the reminder that nags and the one that is missed are the same design problem.")
ext("C226", " Report 76 (Way of Life): the app-icon badge draws NEG_BADGE 13 ('badge nags', 4.38★) and BUG_BADGE 5.")
ext("C010", " Report 76 (Way of Life): NEG_BACKFILL 39 (0.50%, 3.79★, 2012 → 2024, 'hard to log past days'; jp 4.22×) against PR_BACKFILL 8 at 5.00★ once possible; REQ_FUTURE_ENTRY 9 want to mark future days; REQ_DAY_ROLLOVER 9 want a custom day end.")
ext("C170", " Report 76 (Way of Life): REQ_DAY_ROLLOVER 9 (custom day end, 2014 → 2024).")
ext("C172", " Report 76 (Way of Life): per-day notes are free and praised (PR_NOTES 174, 2.24%, 4.86★, 1.53× among purchasers); friction is reaching and searching them (REQ_NOTES_VIEW 13, NEG_NOTES_UX 4) and photos (REQ_PHOTO 9).")
ext("C205", " Report 76 (Way of Life): REQ_NOTES_VIEW 13 — search / view notes across days (2013 → 2026).")
ext("C208", " Report 76 (Way of Life): REQ_PHOTO 9 (4.67★) — photos in notes.")
ext("C045", " Report 76 (Way of Life): tags shipped (PR_TAGS 35, 4.77★, from 2014-06) and REQ_CATEGORIES 37 (0.48%) still ask for groups / sections; REQ_TAG_FILTER 1.")
ext("C073", " Report 76 (Way of Life): REQ_REORDER 16 (0.21%, 2011 → 2025) and NEG_EDIT_NAME 3 ('cannot edit items', 2012 → 2015) — both long since fixed but they recur for years.")
ext("C227", " Report 76 (Way of Life): archive exists (PR_ARCHIVE 14 at 4.93★, 'pause habits') with NEG_ARCHIVE_UX 5 ('cannot find archived items', 4.80★) and REQ_ARCHIVE 10 ('keep data of removed habits').")
ext("C020", " Report 76 (Way of Life): CSV/Excel export is free and praised (PR_EXPORT 50, 4.84★); NEG_EXPORT_FORMAT 4; REQ_IMPORT 6.")
ext("C080", " Report 76 (Way of Life): REQ_THEMES 54 (0.70%, 4.22★) across the whole span 2011 → 2026; themes shipped 2019-07 (Dark, Serenity, Retro C64, Light, Rose; PR_THEMES 14 at 4.86★) with some sold (MON_BUY_ITEMS 27, 16.48× among purchasers); 'this app keeps its dark mode theme locked behind a paid upgrade' (3★).")
ext("C167", " Report 76 (Way of Life): paid themes / add-ons (MON_BUY_ITEMS 27, 4.44★) are bought — 16.48× over-represented among purchasers — but gating dark mode specifically drew a 3★.")
ext("C075", " Report 76 (Way of Life): the interactive walkthrough is praised (PR_ONBOARDING 48, 4.79★; au 4.95×) and the app is 'confusing on first use, simple once learned' — NEG_UI_CONFUSING 81 (1.04%, 3.36★, 12.50% of 2★), NEG_LEARNING_CURVE 17 (4.65★); 'depois do excelente porém extenso tutorial, a gente pega a manha' (after the excellent but long tutorial you get the hang of it, br 4★); BUG_ONBOARDING_LOOP 3 (tutorial stuck).")
ext("C017", " Report 76 (Way of Life): passcode / Face ID lock ships (PR_PASSCODE 7 at 5.00★) and lock-outs are rare but severe (BUG_PASSCODE 7: 'LOCKED OUT OF APP', 1★).")
ext("C096", " Report 76 (Way of Life): passcode / Touch ID / Face ID lock; PR_PRIVACY 12 ('local data, no account', 4.92★); a lock-out is a 1★.")
ext("C271", " Report 76 (Way of Life): MON_PAID_TWICE 3 — 'you have to pay for each iPhone or iPad you use' (1★); MON_FAMILY_SHARING 3.")
ext("C027", " Report 76 (Way of Life): 25 declared languages; REQ_LANG 13 ask for Chinese, Russian, Japanese, Korean, Kazakh, Galician or a working language switch; BUG_LANG 15 translation errors reported in 8 languages; English is the review language of 78 storefronts, Russian is written from 14.")
ext("C255", " Report 76 (Way of Life): reviewers ask for 'a working language switch' (REQ_LANG 13); BUG_LANG 15 (3.60★) across 8 languages.")
ext("C026", " Report 76 (Way of Life): the Russian-speaking group (ru + ua + kz, 584 reviews) over-indexes on purchase/restore failures (ru BUG_PURCHASE 3.29×), subscription objections (2.83×) and platform requests (6.5% vs 4.3%) — and thanks the developer most (ru 1.99×, kz 4.06×).")
ext("C132", " Report 76 (Way of Life): Dropbox-only backup was unusable on the Chinese storefront (17 of 18 complaints, 2014–16) — the app was sold where its data-safety feature could not function.")
ext("C005", " Report 76 (Way of Life): COMP_MENTION 113 (1.46%, 4.29★); PR_BETTER_THAN 428 (5.51%) — the grid of three states and good/bad habits is what users say other trackers lack; leavers name data loss, price or the subscription, returners name simplicity.")
ext("C209", " Report 76 (Way of Life): 16 years with no account — PR_PRIVACY 12 'local data, no account'; the cost is data loss on phone change (C034) rather than a sign-up complaint.")
ext("C011", " Report 76 (Way of Life): REQ_STATS 72 (0.93%, 4.19★), REQ_DATE_RANGE 22, REQ_CHART_CUSTOM 8, REQ_CALENDAR 29 (calendar view, 3.93★) — more statistics and other time ranges on top of free charts.")
ext("C108", " Report 76 (Way of Life): REQ_GOALS 25 (0.32%, 4.20★, 2011 → 2025) — goals / targets; NEG_WEEKLY_GOAL 2.")
ext("C202", " Report 76 (Way of Life): REQ_SOCIAL 23 (0.30%, 4.30★, 2013 → 2026) 'share with friends'; USE_SOCIAL 4; NEG_SOCIAL 1 'unwanted social sharing'.")
ext("C046", " Report 76 (Way of Life): REQ_INTEGRATION 14 (4.29★; ru 5.78×); the listing ships Siri & Shortcuts.")
ext("C048", " Report 76 (Way of Life): REQ_COUNT 129 (1.66%, 4.22★) quantities / several times a day, in every era (0.8–2.9%); NEG_YESNO 36 want a partial or 'yellow' state; §8.4 test an optional count per day as a separate journal type, keeping yes/no as the default.")
ext("C265", " Report 76 (Way of Life): REQ_COUNT 129 and NEG_YESNO 36 ('In my life things aren't always yes or no', 4★) — the binary grid is the product's value and its ceiling; §8.4 counts as a separate journal type, never the default.")
ext("C143", " Report 76 (Way of Life): REQ_COUNT 129 includes 'several times a day'; the yes/no/skip cell cannot hold a count.")
ext("C264", " Report 76 (Way of Life): 'I track 30+ items in under 2 minutes' (5★); PR_FAST 197; NEG_TWO_TAPS 4 — logging cost in seconds is why it survives 13 years of daily use ('almost 9 years since my last review and 13 since the first').")
ext("C155", " Report 76 (Way of Life): the 2023 removal of the old Today widget drew NEG_LOST_FEATURE 7 ('Any updates on when the widget will be fixed?', 3★); §8.8 lists what to keep — the three-state grid, good/bad inversion, skip, charts, the 3-habit free tier.")
ext("C212", " Report 76 (Way of Life): MON_REFUND 9 (0.12%, mean 1.89★) — drivers are a purchase that did not work, an unexpected subscription charge, or a product that did not meet the price ('got my money back', ch 1★); purchaser churn 3 of 349 (0.9%).")
ext("C089", " Report 76 (Way of Life): MON_SALE 3 (5.00★) — discounts are welcomed; 'only offer a reduced price in the first days after installation' (br 5★) is the complaint about timing.")
ext("C214", " Report 76 (Way of Life): 'Ich kann das gleiche auch mit einer einfachen Strichliste machen' (I can do the same with a simple tally sheet, 2★; NEG_SIMPLE 43 at 2.98★, NEG_POINTLESS 15 at 2.53★) — the tally-sheet comparison is the ceiling on a $4.99 unlock for a minority.")
ext("C025", " Report 76 (Way of Life): stated willingness to pay differs by market — 12 yuan (cn), 200 roubles (ru), £50 lifetime (gb) — and price objection is 15.5% of cn vs 4.8% of us.")
ext("C037", " Report 76 (Way of Life): MON_FAMILY_SHARING 3 (family sharing / gifting, 2015 → 2025).")
ext("C101", " Report 76 (Way of Life): REQ_GAMIFY 16 (rewards / achievements, 4.06★) and REQ_SCORE 4 — small against PR_CHAINS 129; the listing ships a scoreboard.")
ext("C051", " Report 76 (Way of Life): REQ_ANDROID 3 in 7,764 reviews.")
ext("C099", " Report 76 (Way of Life): REQ_TIMER 5 (3.20★).")
ext("C050", " Report 76 (Way of Life): REQ_SUBTASKS 6 (to-dos / subtasks, 2014 → 2018).")
ext("C173", " Report 76 (Way of Life): REQ_SUBTASKS 6.")
ext("C053", " Report 76 (Way of Life): REQ_DAY_ROLLOVER 9 — a custom day end.")
ext("C098", " Report 76 (Way of Life): REQ_DATE_RANGE 22 (other time ranges for charts, 4.23★); REQ_ROLLING_VIEW 1.")
ext("C261", " Report 76 (Way of Life): REQ_THEMES 54 'colours / dark mode' across 15 years; REQ_ICONS 3; REQ_COLORBLIND 1 (the listing ships a colour-blind mode).")
ext("C171", " Report 76 (Way of Life): the listing ships a colour-blind mode; REQ_COLORBLIND 1; REQ_FONT 2; REQ_LANDSCAPE 9 (3.44★).")
ext("C110", " Report 76 (Way of Life): MON_UPSELL 13 (2.85★, 'upsell nags', 2014 → 2023); MON_PAYWALL 22 (2.68★).")
ext("C093", " Report 76 (Way of Life): MON_UPSELL 13 (mean 2.85★).")
ext("C185", " Report 76 (Way of Life): PR_DESIGN 602 (7.75%, 4.78★) and NEG_DESIGN 70 (0.90%, 'dated or ugly', 2011 → 2023) — design praise is high but it is simplicity, not looks, that retains for 13 years.")
ext("C001", " Report 76 (Way of Life): MON_FREE_CUT 2 ('free version reduced', 2011 and 2016) — rare here; the free tier held at three items for 16 years.")
ext("C104", " Report 76 (Way of Life): the 2023 move to a subscription was not dated by any reviewer and the corpus cannot say whether lifetime buyers were migrated automatically — the change arrived as a surprise on the restore path ('it said I had to buy premium again', 1★).")
ext("C078", " Report 76 (Way of Life): 11 reviews on cn in one week of 2015-01 report the app crashing immediately after buying premium ('钱扣了就开始闪退，无限闪退' — the money was taken and it started crashing, endlessly, 1★).")
ext("C210", " Report 76 (Way of Life): 'This is not a Free app with in-app purchases. This is a $7 app' (1★) — the free listing with a 3-item cap is read as a mislabelled paid app by some.")
ext("C240", " Report 76 (Way of Life): 'app solicited a review 3 days in, after I paid for the premium version' (4★); §8.7 never prompt right after a purchase.")
ext("C077", " Report 76 (Way of Life): 'money were taken but nothing had changed' (ru 1★); BUG_PURCHASE 9.48× among purchasers.")
ext("C196", " Report 76 (Way of Life): E6 subscription-era reviewers praise 'steady updates' (PR_UPDATE 5.1% of E6, PR_DEV 6.7%) — the visible cadence is what keeps veterans on side while the subscription objection runs underneath.")
ext("C225", " Report 76 (Way of Life): a podcast mention (Tim Ferriss / Kevin Rose, 2014–2016) shows up in reviews for a decade and converts the same day — an earned-media wave (E4 'the podcast wave', 26 of 51 MKT_PRESS) behaves like a promotion.")
ext("C140", " Report 76 (Way of Life): 'journals' rather than habits — items can be anything, good or bad; USE_WORK 16, USE_STUDY 18, USE_FAMILY 13 alongside fitness and health; PR_CUSTOM 206 (2.65%).")
ext("C230", " Report 76 (Way of Life): no sync at all for 16 years — REQ_SYNC 139 — so this corpus has zero sync-conflict complaints; the data-loss path is the phone change, not the merge.")
ext("C035", " Report 76 (Way of Life): a counter-example — no account, no sync, local-only for 16 years at 4.62★; the cost shows as data loss on phone change (U_DATA_RISK 123, 1.58%) and REQ_SYNC 139 in every era, not as a sign-up complaint; PR_PRIVACY 12 praise the absence.")
ext("C063", " Report 76 (Way of Life): the free trial on the subscription (E6) — 'My trial ends Saturday' (2★).")

